<section class="mt-8 rounded-[2.5rem] bg-white/85 p-6 shadow-card sm:p-8"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p class="font-headline text-xl font-extrabold text-coralDark">Inventory</p><h2 class="font-headline text-4xl font-extrabold">Manage products and stock</h2><p class="mt-2 font-bold text-softText">Add products, edit prices, and update stock levels.</p></div><a href="{{ route('admin.inventory') }}" class="rounded-full bg-coral px-5 py-3 text-center text-sm font-extrabold text-white">Open inventory</a></div><div class="mt-6 grid gap-4 md:grid-cols-2 xl:grid-cols-3">@foreach($products->take(6) as $product)<div class="rounded-2xl bg-cream p-5"><div class="flex items-center justify-between"><h3 class="font-headline text-2xl font-extrabold">{{ $product->name }}</h3><span class="rounded-full bg-mint px-3 py-1 text-xs font-black">{{ $product->stock }} left</span></div><p class="mt-1 text-sm font-bold text-softText">{{ $product->category }} · ₱{{ number_format($product->price, 2) }}</p></div>@endforeach</div></section>
<section class="mt-8 rounded-[2.5rem] bg-white/85 p-6 shadow-card sm:p-8"><p class="font-headline text-xl font-extrabold text-coralDark">Order fulfillment</p><h2 class="font-headline text-4xl font-extrabold">Update customer delivery status</h2><div class="mt-6 space-y-3">@forelse($orders->take(12) as $order)<div class="flex flex-col gap-3 rounded-2xl bg-cream p-4 md:flex-row md:items-center md:justify-between"><div><p class="font-extrabold">#{{ $order->reference }} · {{ $order->customer_name }}</p><p class="text-sm font-bold text-softText">₱{{ number_format($order->total, 2) }} · {{ ucfirst($order->status) }}</p></div><form method="POST" action="{{ route('admin.order.status', $order->id) }}" class="flex items-center gap-2">@csrf @method('PATCH')<select name="status" class="rounded-xl border-2 border-peach bg-white px-3 py-2 text-sm font-bold"><option value="pending" @selected($order->status === 'pending')>Pending</option><option value="processing" @selected($order->status === 'processing')>Processing</option><option value="packed" @selected($order->status === 'packed')>Packed</option><option value="shipped" @selected($order->status === 'shipped')>Shipped</option><option value="delivered" @selected($order->status === 'delivered')>Delivered</option><option value="cancelled" @selected($order->status === 'cancelled')>Cancelled</option></select><button class="rounded-full bg-coral px-4 py-2 text-sm font-extrabold text-white" type="submit">Save</button></form></div>@empty<p class="rounded-2xl bg-cream p-5 font-bold text-softText">No customer orders yet.</p>@endforelse</div></section>
